SELECT COUNT(*) AS low_rating_reviews
FROM reviews
WHERE parent_asin = 'B08YZ8219S' AND rating BETWEEN 1 AND 2;

SELECT AVG(rating) AS avg_rating, COUNT(*) AS review_count
FROM reviews
WHERE parent_asin = 'B0C46SPKJ9';

SELECT ROUND(AVG(rating), 2) AS avg_rating
FROM reviews
WHERE parent_asin = 'B0C46SPKJ9';
